std::string_view copy(const ui::Context& ui, Copy key) {
    const auto locale=ui.locale();
    const size_t language=locale=="de" || locale.starts_with("de-") ? 1 : locale=="ro" || locale.starts_with("ro-") ? 2 : 0;
    return words[static_cast<size_t>(key)][language];
}
